<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import type {ViewModel} from '../app/useWorkspace';
import {newWorldEntry,worldbookWarnings,worldEntryWarnings,resolveWorldbooks,WORLD_FILE_LIMIT,type Worldbook,type WorldEntry} from '../domain/worldbooks';
import DialogShell from './DialogShell.vue';
const props=defineProps<{w:ViewModel}>();
const query=ref(''),entryDraft=ref<WorldEntry>(),entryBookId=ref(''),bookDraft=ref<Worldbook>(),deletingBook=ref<Worldbook>(),deletingEntry=ref<WorldEntry>(),testInput=ref(''),preview=ref<string[]>();
const locked=computed(()=>props.w.busy||props.w.workingMemory);
const book=computed(()=>props.w.currentWorldbook);
const shown=computed(()=>book.value?.entries.filter(e=>!query.value.trim()||(e.title+' '+e.content+' '+e.keys.join(' ')).toLowerCase().includes(query.value.trim().toLowerCase()))||[]);
const warnings=computed(()=>book.value?worldbookWarnings(book.value):[]);
const keyText=ref(''),secondaryText=ref('');
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v));
watch(()=>book.value?.id,()=>{query.value='';preview.value=undefined;});
async function importFiles(event:Event){const el=event.target as HTMLInputElement;try{for(const file of Array.from(el.files||[])){if(file.size>WORLD_FILE_LIMIT)throw new Error('单份世界书文件不能超过 5MB');props.w.importUserWorldbook(await file.text(),file.name);}}catch(e){props.w.problem=e instanceof Error?e.message:'世界书读取失败';}finally{el.value='';}}
function editEntry(e?:WorldEntry){if(!book.value)return;entryBookId.value=book.value.id;entryDraft.value=clone(e||newWorldEntry());keyText.value=entryDraft.value.keys.join('\n');secondaryText.value=entryDraft.value.secondaryKeys.join('\n');}
function saveEntry(){if(!entryDraft.value)return;const split=(s:string)=>s.split(/[\n,，]/).map(k=>k.trim()).filter(Boolean);entryDraft.value.keys=split(keyText.value);entryDraft.value.secondaryKeys=split(secondaryText.value);props.w.saveWorldEntry(entryBookId.value,clone(entryDraft.value));if(!props.w.problem)entryDraft.value=undefined;}
function toggle(e:WorldEntry){if(book.value)props.w.saveWorldEntry(book.value.id,{...clone(e),enabled:!e.enabled});}
function saveBook(){if(!bookDraft.value)return;props.w.updateWorldbook(clone(bookDraft.value));if(!props.w.problem)bookDraft.value=undefined;}
function test(){try{const ctx={messages:[...(props.w.active?[props.w.active.opening,...props.w.active.turns.flatMap(t=>{const v=t.variants[t.selected];return v?.status==='complete'?[t.input,v.text]:[];})]:[]),testInput.value],userName:props.w.active?.persona.name||'user',charName:props.w.localService?.narratorName||'群星共振世界卡',seed:'preview'};const result=resolveWorldbooks(props.w.worldbooks.filter(b=>props.w.boundWorldbookIds.includes(b.id)),ctx);preview.value=[...result.activated.map(id=>{for(const b of props.w.worldbooks)for(const e of b.entries)if(b.id+':'+e.id===id)return b.name+'／'+e.title;return id;}),...result.warnings];props.w.problem='';}catch(e){props.w.problem=e instanceof Error?e.message:'测试失败';}}
</script>
<template>
  <section class="surface worldbook-page">
    <header class="page-heading"><h1>世界书</h1><span class="tag">服务器内置设定已保留</span></header>
    <details v-if="w.worldbookRuntimeWarnings.length" class="worldbook-warning"><summary>最近一次剧情的世界书提示</summary><ul><li v-for="line in w.worldbookRuntimeWarnings" :key="line">{{line}}</li></ul></details>
    <div class="worldbook-layout">
      <aside class="worldbook-library">
        <h2>我的世界书</h2>
        <div class="actions"><button :disabled="locked" @click="w.addWorldbook()">新建</button><label class="worldbook-upload">导入 JSON<input type="file" multiple accept=".json,application/json" :disabled="locked" @change="importFiles" /></label></div>
        <p class="worldbook-scope">{{w.active?'当前存档：'+w.active.name:'新游戏默认使用'}}</p>
        <p v-if="!w.worldbooks.length" class="empty">还没有用户世界书</p>
        <article v-for="b in w.worldbooks" :key="b.id" class="worldbook-library-row" :class="{selected:book?.id===b.id}">
          <label class="toggle"><input type="checkbox" :checked="w.boundWorldbookIds.includes(b.id)" :disabled="locked" :aria-label="'使用世界书 '+b.name" @change="w.bindWorldbook(b.id,($event.target as HTMLInputElement).checked)" /></label>
          <button class="worldbook-name" @click="w.selectedWorldbookId=b.id">{{b.name}}<small>{{b.entries.length}} 条</small></button>
        </article>
      </aside>
      <div v-if="book" class="worldbook-editor">
        <header class="worldbook-toolbar"><h2>{{book.name}}</h2><div class="actions"><button :disabled="locked" @click="bookDraft=clone(book)">世界书设置</button><button :disabled="locked" @click="w.duplicateWorldbook()">复制</button><button :disabled="locked" @click="w.exportUserWorldbook()">导出</button><button :disabled="locked" @click="deletingBook=book">删除</button></div></header>
        <details v-if="warnings.length" class="worldbook-warning"><summary>兼容提示（{{warnings.length}} 条）</summary><p>以下条目保留在本地及导出文件中，暂不触发：</p><ul><li v-for="line in warnings" :key="line">{{line}}</li></ul></details>
        <div class="field-grid"><label>搜索条目<input v-model="query" placeholder="名称、关键词或内容" /></label><div class="actions"><button class="primary" :disabled="locked" @click="editEntry()">增加条目</button></div></div>
        <p v-if="!shown.length" class="empty">{{query?'没有匹配的条目':'还没有条目'}}</p>
        <details v-for="e in shown" :key="e.id" class="worldbook-entry" :class="{'worldbook-disabled':!e.enabled}">
          <summary><span>{{e.constant?'🔵':'🟢'}} {{e.title||'未命名条目'}}</span><span class="worldbook-entry-meta">{{e.enabled?'已启用':'已关闭'}} · {{e.order}}<span v-if="worldEntryWarnings(e).length"> · 暂不兼容</span></span></summary>
          <div class="worldbook-entry-body"><p v-if="e.keys.length" class="worldbook-keywords">{{e.keys.join('、')}}</p><p class="worldbook-content">{{e.content||'（空条目）'}}</p><div class="actions"><button :disabled="locked" @click="toggle(e)">{{e.enabled?'关闭':'启用'}}</button><button :disabled="locked" @click="editEntry(e)">编辑</button><button :disabled="locked" @click="deletingEntry=e">删除</button></div></div>
        </details>
        <details class="subsection"><summary>测试触发</summary><label>测试输入<textarea v-model="testInput" rows="3" /></label><button @click="test">检查启用的世界书</button><div v-if="preview" role="status"><p v-if="!preview.length">未触发条目</p><ul v-else><li v-for="item in preview" :key="item">{{item}}</li></ul></div></details>
      </div>
    </div>
    <DialogShell v-if="bookDraft" title="世界书设置" @close="bookDraft=undefined"><form @submit.prevent="saveBook"><fieldset :disabled="locked"><label>名称<input v-model="bookDraft.name" required maxlength="200" /></label><div class="field-grid"><label>默认扫描深度（消息条数）<input v-model.number="bookDraft.scanDepth" type="number" min="0" max="1000" required /></label><label>本书预算（字符）<input v-model.number="bookDraft.budget" type="number" min="100" max="100000" required /></label></div><label class="toggle"><input v-model="bookDraft.recursive" type="checkbox" />递归触发</label><label class="toggle"><input v-model="bookDraft.caseSensitive" type="checkbox" />区分大小写</label><label class="toggle"><input v-model="bookDraft.wholeWords" type="checkbox" />英文整词匹配</label><button class="primary" type="submit">保存</button></fieldset></form></DialogShell>
    <DialogShell v-if="entryDraft" title="世界书条目" @close="entryDraft=undefined"><form @submit.prevent="saveEntry"><fieldset :disabled="locked">
      <label>名称<input v-model="entryDraft.title" maxlength="500" /></label><div class="actions"><label class="toggle"><input v-model="entryDraft.enabled" type="checkbox" />启用</label><label class="toggle"><input v-model="entryDraft.constant" type="checkbox" />常驻</label></div>
      <label>主要关键词<textarea v-model="keyText" rows="2" placeholder="一行一个，或使用逗号分隔" /></label><label>次要关键词<textarea v-model="secondaryText" rows="2" /></label>
      <div class="field-grid"><label class="toggle"><input v-model="entryDraft.selective" type="checkbox" />使用次要关键词</label><label>匹配逻辑<select v-model.number="entryDraft.logic"><option :value="0">AND ANY：至少一个次要词</option><option :value="3">AND ALL：全部次要词</option><option :value="2">NOT ANY：没有次要词</option><option :value="1">NOT ALL：次要词不全出现</option></select></label></div>
      <label>内容<textarea v-model="entryDraft.content" rows="10" maxlength="200000" /></label>
      <div class="field-grid"><label>插入位置<select v-model.number="entryDraft.position"><option :value="0">角色定义之前</option><option :value="1">角色定义之后</option><option :value="4">聊天指定深度</option><option v-if="![0,1,4].includes(entryDraft.position)" :value="entryDraft.position">原文件位置 {{entryDraft.position}}（暂不支持）</option></select></label><label>插入顺序<input v-model.number="entryDraft.order" type="number" min="-100000" max="100000" required /></label><label v-if="entryDraft.position===4">聊天深度<input v-model.number="entryDraft.depth" type="number" min="0" max="1000" required /></label><label v-if="entryDraft.position===4">消息角色<select v-model="entryDraft.role"><option value="system">System</option><option value="user">User</option><option value="assistant">Assistant</option></select></label></div>
      <details><summary>更多触发设置</summary><div class="field-grid"><label>扫描深度（空白使用世界书设置）<input :value="entryDraft.scanDepth??''" type="number" min="0" max="1000" @input="entryDraft.scanDepth=($event.target as HTMLInputElement).value===''?null:Number(($event.target as HTMLInputElement).value)" /></label><label>触发概率 %<input v-model.number="entryDraft.probability" type="number" min="0" max="100" required /></label><label>大小写<select v-model="entryDraft.caseSensitive"><option :value="null">使用世界书设置</option><option :value="true">区分</option><option :value="false">不区分</option></select></label><label>英文整词<select v-model="entryDraft.wholeWords"><option :value="null">使用世界书设置</option><option :value="true">开启</option><option :value="false">关闭</option></select></label></div><label class="toggle"><input v-model="entryDraft.useProbability" type="checkbox" />启用概率</label><label class="toggle"><input v-model="entryDraft.excludeRecursion" type="checkbox" />不被递归激活</label><label class="toggle"><input v-model="entryDraft.preventRecursion" type="checkbox" />本条目不触发后续递归</label><label>从第几层递归开始（0 为立即）<input v-model.number="entryDraft.delayUntilRecursion" type="number" min="0" max="20" required /></label></details>
      <p v-if="worldEntryWarnings(entryDraft).length" class="worldbook-warning">暂不触发：{{worldEntryWarnings(entryDraft).join('、')}}</p><button class="primary" type="submit">保存条目</button>
    </fieldset></form></DialogShell>
    <DialogShell v-if="deletingBook" title="删除世界书？" @close="deletingBook=undefined"><p>删除「{{deletingBook.name}}」及其 {{deletingBook.entries.length}} 条内容，并解除所有存档的绑定。</p><div class="actions"><button @click="deletingBook=undefined">取消</button><button :disabled="locked" @click="w.removeWorldbook(deletingBook.id);deletingBook=undefined">确认删除</button></div></DialogShell>
    <DialogShell v-if="deletingEntry&&book" title="删除条目？" @close="deletingEntry=undefined"><p>{{deletingEntry.title}}</p><div class="actions"><button @click="deletingEntry=undefined">取消</button><button :disabled="locked" @click="w.removeWorldEntry(book.id,deletingEntry.id);deletingEntry=undefined">确认删除</button></div></DialogShell>
  </section>
</template>
<style scoped>
.page-heading,.worldbook-toolbar{display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap}.worldbook-layout{display:grid;grid-template-columns:minmax(190px,260px) minmax(0,1fr);gap:1.5rem}.worldbook-library{border-right:1px solid var(--color-border);padding-right:1rem}.worldbook-library-row{display:flex;align-items:center;gap:.5rem;border:1px solid transparent;border-radius:8px;margin:.5rem 0;padding:.3rem}.worldbook-library-row.selected{border-color:var(--color-accent);background:#afcdf710}.worldbook-name{text-align:left;flex:1;min-width:0;overflow-wrap:anywhere}.worldbook-name small{display:block;opacity:.65;margin-top:.3rem}.worldbook-upload{display:inline-flex;align-items:center;position:relative;overflow:hidden;border:1px solid var(--color-border);border-radius:6px;padding:.5rem .7rem;cursor:pointer}.worldbook-upload input{position:absolute;opacity:0;inset:0;width:100%;cursor:pointer}.worldbook-scope,.worldbook-entry-meta{font-size:.85rem;opacity:.75}.worldbook-editor{min-width:0}.worldbook-entry{border:1px solid var(--color-border);border-radius:8px;margin:.6rem 0}.worldbook-entry>summary{padding:1rem;cursor:pointer;overflow-wrap:anywhere}.worldbook-entry-meta{float:right;margin-left:.7rem}.worldbook-entry-body{padding:0 1rem 1rem}.worldbook-content{white-space:pre-wrap;overflow-wrap:anywhere;max-height:24rem;overflow:auto;line-height:1.7}.worldbook-disabled{opacity:.6}.worldbook-keywords{color:var(--color-accent)}.worldbook-warning{color:var(--color-muted);margin:.8rem 0;overflow-wrap:anywhere}.worldbook-warning ul{max-height:18rem;overflow:auto}fieldset{border:0;margin:0;padding:0;min-width:0}form label{margin:.7rem 0}summary{cursor:pointer}.worldbook-page :deep(.dialog-shell){max-width:850px}@media(max-width:760px){.worldbook-layout{grid-template-columns:1fr}.worldbook-library{border-right:0;border-bottom:1px solid var(--color-border);padding:0 0 1rem}.worldbook-entry-meta{float:none;display:block;margin:.5rem 0 0}}
</style>
